import type { ExpoConfig } from "expo/config";

// One app for iPhone, iPad and Android. android/ and ios/ are generated by
// `expo prebuild` (continuous native generation) and never committed.
const config: ExpoConfig = {
	name: "Retrospend",
	slug: "retrospend",
	scheme: "retrospend",
	version: "0.1.0",
	// The web client is the Next app at the repo root, not an Expo web build.
	platforms: ["ios", "android"],
	orientation: "default",
	// Light and dark follow the system; colors come from @retrospend/tokens.
	userInterfaceStyle: "automatic",
	ios: {
		bundleIdentifier: "app.retrospend",
		// Daniel Miller's team. Prebuild writes it as DEVELOPMENT_TEAM, so
		// Xcode's automatic signing knows whose profiles to create.
		appleTeamId: "6NHZWHQX37",
		supportsTablet: true,
		// Stage Manager, Split View and Slide Over stay available on iPad.
		requireFullScreen: false,
		infoPlist: {
			// App Review justification: the app connects to user-hosted servers,
			// which may use plain http on a home network. The connect screen
			// warns before it saves one (owner decision, 2026-10-22).
			NSAppTransportSecurity: { NSAllowsArbitraryLoads: true },
		},
	},
	android: {
		package: "app.retrospend",
		// Edge-to-edge is always on (React Native 0.86, targetSdk 36); screens
		// pad with safe-area insets.
		predictiveBackGestureEnabled: true,
	},
	plugins: [
		"expo-router",
		"expo-localization",
		"expo-secure-store",
		// Android half of the http decision above.
		"./plugins/with-cleartext-servers",
		// iOS 27 SDK apps must use the UIScene life cycle.
		"./plugins/with-ios-scene-lifecycle",
	],
};

export default config;
